// Independent auditor probe (no database): PLAY-01 player-move policy against the actual
// upstream registry, all three facades plus the private persistence wrapper, executable
// identity binding, injected-transcript rejection and RULE-03 replay regressions.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { PLAYER_MOVES, isPlayerMove } from './packages/contracts/dist/player-moves.js';
import * as adapter from './packages/engine-adapter/dist/index.js';
import { createLabMatch } from './packages/engine-lab/dist/index.js';
import { fingerprintExecutableIdentity } from './packages/engine-adapter/dist/code-identity.js';
import { KERNEL_IDENTITY } from './vendor/tcg-engines/dist/kernel.js';

const REG = 'vendor/tcg-engines/upstream/submodules/lorcana/packages/lorcana/lorcana-engine/src/runtime-moves/index.ts';
const src = readFileSync(REG, 'utf8');
const body = src.slice(src.indexOf('export const lorcanaRuntimeMoves = {'), src.indexOf('} satisfies LorcanaRuntimeMoveRegistry'));
const registry = [...body.matchAll(/^\s+([a-zA-Z]+),\s*$/gm)].map(m => m[1]);
assert.equal(new Set(registry).size, registry.length);
assert.equal(registry.length, 25, 'registry size ' + registry.length);
const allow = [...PLAYER_MOVES];
assert.equal(allow.length, 13);
assert.ok(Object.isFrozen(PLAYER_MOVES));
for (const m of allow) assert.ok(registry.includes(m), 'allowlisted move absent from registry: ' + m);
const refusedRegistry = registry.filter(m => !allow.includes(m)).sort();
assert.deepEqual(refusedRegistry, ['forfeitGame', 'manualDryCard', 'manualExertCard', 'manualMoveCard', 'manualPassTurn', 'manualReadyCard', 'manualSetDamage', 'manualSetInkDrops', 'manualSetLore', 'manualShuffleDeck', 'sing', 'singTogether'].sort());
const kernelText = readFileSync('vendor/tcg-engines/dist/kernel.js', 'utf8');
for (const m of registry) assert.ok(kernelText.includes(m), 'compiled kernel lacks ' + m);
const hostile = [...refusedRegistry, 'toString', 'valueOf', 'hasOwnProperty', '__proto__', 'constructor', 'unknownMove', 'passturn', 'PassTurn', ' passTurn', 'passTurn '];
for (const m of hostile) assert.equal(isPlayerMove(m), false, m);
for (const v of [null, undefined, 1, {}, ['passTurn'], { toString: () => 'passTurn' }]) assert.equal(isPlayerMove(v), false);

const OPEN = s => [[s.status().choosingFirstPlayer ?? 'p1', 'chooseWhoGoesFirst', { playerId: 'p1' }], ['p1', 'alterHand', { cardsToMulligan: [] }], ['p2', 'alterHand', { cardsToMulligan: [] }]];
const cmd = (m, actor, move, input = {}, id) => ({ actor, move, input, commandId: id ?? (actor + '-' + move + '-' + m.status().revision), expectedRevision: m.status().revision, timestamp: 0 });
const facades = {
  server: () => adapter.createQualificationMatch({ players: ['p1', 'p2'], startTimestamp: 0 }),
  'Lab qualification': () => createLabMatch({ mode: 'qualification', fixture: 'synthetic', seed: 'audit', players: ['p1', 'p2'] }),
  'Lab advanced-sandbox': () => createLabMatch({ mode: 'advanced-sandbox', fixture: 'synthetic', seed: 'audit', players: ['p1', 'p2'] }),
  'private persistence': () => adapter.createPrivateMatch({ matchId: 'audit-policy', players: ['p1', 'p2'], startTimestamp: 0 }),
};
const facadeResults = {};
for (const [name, make] of Object.entries(facades)) {
  const m = make();
  try {
    for (const [a, mv, inp] of OPEN(m)) assert.equal(m.submit(cmd(m, a, mv, inp)).accepted, true, name + ' opening ' + mv);
    const before = JSON.stringify(m.status()), cp = m.checkpoint?.().archive;
    let refused = 0;
    // Both the active and the non-active player; RUN054's exact winning payload included.
    for (const actor of ['p1', 'p2']) for (const move of hostile) {
      const r = m.submit(cmd(m, actor, move, { amount: 20, playerId: actor, winnerId: actor, cardId: 'x', damage: 9 }, 'bad-' + actor + '-' + move));
      assert.deepEqual(r, { accepted: false, code: 'MOVE_FORBIDDEN' }, name + ' ' + actor + ' ' + move);
      assert.equal(JSON.stringify(m.status()), before, name + ' state changed by ' + move);
      refused++;
    }
    if (cp !== undefined) assert.equal(m.checkpoint().archive, cp, name + ' forbidden attempts entered the private transcript');
    // Allowlisted moves still reach the engine: the active player passes, then the other concedes.
    // p1 was chosen to start: the non-active p2 cannot pass, the active p1 can.
    const pass = ['p2', 'p1'].map(a => m.submit(cmd(m, a, 'passTurn', {}, 'pass-' + a)).accepted);
    assert.deepEqual(pass, [false, true], name + ' pass authority: ' + JSON.stringify(pass));
    assert.equal(m.submit(cmd(m, 'p1', 'concede', {}, 'concede')).accepted, true);
    assert.equal(m.status().ended, true); assert.equal(m.status().winner, 'p2');
    facadeResults[name] = refused;
  } finally { m.dispose(); }
}

// Executable identity binds the compiled shared policy bytes.
const dist = new URL('./packages/engine-adapter/dist/', 'file://' + process.cwd() + '/');
const kernelUrl = new URL('./vendor/tcg-engines/dist/kernel.js', 'file://' + process.cwd() + '/');
const policyUrl = new URL('./packages/contracts/dist/player-moves.js', 'file://' + process.cwd() + '/');
const withPolicy = fingerprintExecutableIdentity(dist, kernelUrl, KERNEL_IDENTITY, policyUrl);
const withoutPolicy = fingerprintExecutableIdentity(dist, kernelUrl, KERNEL_IDENTITY);
assert.equal(withPolicy, adapter.PERSISTENT_ENGINE_IDENTITY, 'identity must equal compiled adapter+kernel+policy');
assert.notEqual(withoutPolicy, withPolicy);

// Private checkpoint: an injected debug command or swapped recorded result with a recomputed
// storage digest is refused on restore (the digest is integrity, re-execution is the check).
const digest = a => createHash('sha256').update('private-match-checkpoint-v1\0').update(a).digest('hex');
const canonical = v => { const o = x => Array.isArray(x) ? x.map(o) : x && typeof x === 'object' ? Object.fromEntries(Object.entries(x).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0).map(([k, y]) => [k, o(y)])) : x; return JSON.stringify(o(JSON.parse(JSON.stringify(v)))); };
const pm = adapter.createPrivateMatch({ matchId: 'audit-inject', players: ['p1', 'p2'], startTimestamp: 0 });
let injections = 0;
try {
  for (const [a, mv, inp] of OPEN(pm)) pm.submit(cmd(pm, a, mv, inp));
  const good = pm.checkpoint();
  const r0 = adapter.restorePrivateMatch(good, 'audit-inject'); assert.equal(r0.checkpoint().archive, good.archive); r0.dispose();
  const base = JSON.parse(good.archive), last = base.transcript.commands.at(-1);
  const forged = [
    t => t.transcript.commands.push({ ...structuredClone(last), command: { ...last.command, commandId: 'inj', move: 'manualSetLore', input: { amount: 20, playerId: 'p2' }, expectedRevision: last.command.expectedRevision + 1 }, result: { accepted: true, code: null } }),
    t => { t.transcript.commands.at(-1).command.move = 'manualSetLore'; },
    t => { t.transcript.commands.at(-1).command.actor = 'p1'; },
    t => { t.transcript.setup.players = ['p2', 'p1']; },
    t => { t.transcript.final.status.winner = 'p1'; },
    t => { t.transcript.seedCommitment = '0'.repeat(64); },
    t => { t.transcript.rngVersion = 'other'; },
    t => { t.version = 2; },
    t => { t.purpose = 'synthetic-rule03'; },
  ];
  for (const f of forged) {
    const t = structuredClone(base); f(t); const a = canonical(t);
    assert.throws(() => adapter.restorePrivateMatch({ archive: a, digest: digest(a) }, 'audit-inject'), /Checkpoint restore rejected/);
    injections++;
  }
  // Non-canonical but semantically equal bytes are refused too.
  const spaced = JSON.stringify(base, null, 1);
  assert.throws(() => adapter.restorePrivateMatch({ archive: spaced, digest: digest(spaced) }, 'audit-inject'), /Checkpoint restore rejected/);
  // Extra keys on the checkpoint object or accessor-bearing objects are refused without invoking accessors.
  let touched = 0;
  const trap = { archive: good.archive }; Object.defineProperty(trap, 'digest', { enumerable: true, get() { touched++; return good.digest; } });
  assert.throws(() => adapter.restorePrivateMatch(trap, 'audit-inject'), /Checkpoint restore rejected/); assert.equal(touched, 0);
  assert.throws(() => adapter.restorePrivateMatch({ ...good, extra: 1 }, 'audit-inject'), /Checkpoint restore rejected/);
} finally { pm.dispose(); }

// The ordinary facade still exposes no live checkpoint/seed; RULE-03 completed replay still verifies.
let replays = 0, tampers = 0;
for (let i = 0; i < 6; i++) {
  const m = adapter.createQualificationMatch({ players: ['p1', 'p2'], startTimestamp: 0 });
  try {
    assert.equal('checkpoint' in m, false); assert.equal('seed' in m.status(), false);
    assert.throws(() => m.exportReplay(), /completed/);
    for (const [a, mv, inp] of OPEN(m)) m.submit(cmd(m, a, mv, inp));
    m.submit(cmd(m, i % 2 ? 'p1' : 'p2', 'concede'));
    const rep = m.exportReplay(), d = createHash('sha256').update('completed-private-replay-v1\0').update(rep.archive).digest('hex');
    assert.equal(rep.digest, d);
    assert.equal(adapter.verifyCompletedReplay(rep.archive, rep.digest).verified, true); replays++;
    const t = JSON.parse(rep.archive); t.commands[0].randomOutcomes = []; const a = canonical(t);
    assert.throws(() => adapter.verifyCompletedReplay(a, createHash('sha256').update('completed-private-replay-v1\0').update(a).digest('hex')), /rejected/); tampers++;
  } finally { m.dispose(); }
}
console.log(JSON.stringify({ registry: registry.length, allowlisted: allow.length, refusedRegistry: refusedRegistry.length, hostileNames: hostile.length, facadeRefusals: facadeResults, identityBindsPolicy: true, restoreForgeriesRefused: injections + 3, completedReplaysVerified: replays, replayTampersRefused: tampers }));
console.log('PASS auditor PLAY-01 policy probe: 13-move allowlist equals the upstream registry minus 9 debug, forfeitGame and 2 unimplemented moves; all four facades refuse every other name for both players without state or transcript change; identity binds policy bytes; forged checkpoints refused; RULE-03 replay intact');
